-- H2 projections for the "My" page dashboard and to-do aggregation.
CREATE TABLE IF NOT EXISTS opportunities(id BIGINT PRIMARY KEY,campus_id BIGINT,title VARCHAR(256),summary VARCHAR(1000),deadline TIMESTAMP,status VARCHAR(32),source_type VARCHAR(16),created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS reminders(id BIGINT PRIMARY KEY,user_id BIGINT,target_type VARCHAR(32),target_id BIGINT,remind_at TIMESTAMP,status VARCHAR(32) DEFAULT 'pending',created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservations(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,slot_id BIGINT,seat_no INT DEFAULT 0,status VARCHAR(32),source_type VARCHAR(16),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS work_orders(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,assignee_id BIGINT,category VARCHAR(32),location VARCHAR(255),description VARCHAR(1024),urgency VARCHAR(16),status VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS resources(id BIGINT PRIMARY KEY,campus_id BIGINT,region_id BIGINT,type VARCHAR(32),name VARCHAR(128),capacity INT,status VARCHAR(32),source_type VARCHAR(16),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS resource_slots(id BIGINT PRIMARY KEY,resource_id BIGINT,slot_date DATE,start_time TIME,end_time TIME,capacity INT,status VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations(id BIGINT PRIMARY KEY,campus_id BIGINT,type VARCHAR(32),title VARCHAR(128),context_type VARCHAR(32),context_id BIGINT,access_revoked_at TIMESTAMP,created_by BIGINT,version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_members(id BIGINT PRIMARY KEY,conversation_id BIGINT,user_id BIGINT,unread_count INT DEFAULT 0,last_read_message_id BIGINT,last_read_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,type VARCHAR(32),title VARCHAR(128),content VARCHAR(512),target_type VARCHAR(32),target_id BIGINT,read_at TIMESTAMP,dedup_key VARCHAR(64) UNIQUE,created_at TIMESTAMP);
